fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let mut seed: i32 = host::display::state_get(0);
    seed = seed * 1103515245 + 12345;
    let d1: i32 = ((seed >> 16) & 32767) % 6 + 1;
    seed = seed * 1103515245 + 12345;
    let d2: i32 = ((seed >> 16) & 32767) % 6 + 1;
    host::display::state_set(0, seed);
    let bin: i32 = 10 + d1 + d2 - 2;
    host::display::state_set(bin, host::display::state_get(bin) + 1);
    host::display::state_set(1, host::display::state_get(1) + 1);
    host::display::clear(0x000000);
    let mut mx: i32 = 1;
    let mut i: i32 = 0;
    while i < 11 {
        if host::display::state_get(10 + i) > mx { mx = host::display::state_get(10 + i); }
        i = i + 1;
    }
    let bw: i32 = (w - 24) / 11;
    let chh: i32 = h - 90;
    i = 0;
    while i < 11 {
        let v: i32 = host::display::state_get(10 + i);
        let bh: i32 = v * chh / mx;
        host::display::fill_rect(12 + i * bw, h - 44 - bh, bw - 4, bh, 0x30a0ff);
        host::display::draw_number(12 + i * bw + 2, h - 34, i + 2, 0x808080, 1);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "ROLLS", 0x808080, 1);
    host::display::draw_number(60, 8, host::display::state_get(1), 0xffffff, 1);
    host::display::present();
}
